{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Depression is a very common psychiatric disorder in worldwide. Globally, Human Immunodeficiency Virus (HIV) is highly prevalent among women, and are disproportionately affected by depression. Antiretroviral Therapy (ART) adherence which could highly be affected by depression is yet to be explored effectively. Depression affects overall poor HIV clinical outcomes, socioeconomic and social interactions. However, it is not well understood specifically how depression affects ART adherence in women living with HIV (WLWHIV).",
      "reason": "The background describes the current state of knowledge (depression common, WLWHIV disproportionately affected, depression affects HIV outcomes) and explicitly states the uncertainty that it is 'not well understood specifically how depression affects ART adherence in women living with HIV.'"
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Investigating the effects of depression on ART adherence is critical in order to develop nuanced new evidence to address non-adherence in WLWHIV.",
      "reason": "The manuscript explicitly states the importance and need for the review, noting that investigating this effect is 'critical' to develop evidence to address non-adherence among women living with HIV."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes existing similar systematic reviews, justifies the need relative to them, or cites prior reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_16",
      "quote": "the following information extracted: the first author, year of publication, study design, country where the study was held, exposure (depression), outcome (ART adherence), sample size, AOR and RR, with 95% CI, and tool.",
      "reason": "This review examines an exposure (depression) and outcome (ART adherence), not an intervention; thus describing an intervention mechanism is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_16",
      "quote": "the following information extracted: the first author, year of publication, study design, country where the study was held, exposure (depression), outcome (ART adherence), sample size, AOR and RR, with 95% CI, and tool.",
      "reason": "The review is not of a complex intervention or delivery context (it assesses the effect of an exposure), so a logic model for intervention components is not applicable."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4; text_5",
      "quote": "To conduct a meta-analysis on the correlation between depression and adherence to antiretroviral therapy among women living with HIV in the globe.\n\nUsing population, exposed and outcome approach, we searched Scopus, PubMed, EMBASE, Cochrane Library, Psych info, Web of science and google scholar for cohort and cross-sectional studies globally.",
      "reason": "The objective is explicitly stated (meta-analysis on the correlation between depression and ART adherence among women living with HIV) and the methods state a question-formulation framework ('population, exposed and outcome approach'), which explicitly frames the review question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4; text_5",
      "quote": "To conduct a meta-analysis on the correlation between depression and adherence to antiretroviral therapy among women living with HIV in the globe.\n\nUsing population, exposed and outcome approach, we searched Scopus, PubMed, EMBASE, Cochrane Library, Psych info, Web of science and google scholar for cohort and cross-sectional studies globally.",
      "reason": "The review addresses an observational correlation (depression and ART adherence) using a population-exposure-outcome framework rather than evaluating intervention effects; therefore PICO-stated planned comparisons for interventions do not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13; text_11",
      "quote": "Inclusion criteria. Peer reviewed cross-sectional and cohort study designed from across the world, published in English from 1 January 2000 to 30 December 2022 were included in the final analysis. Cross-sectional studies reporting an association between depression and ART adherence and cohort studies reporting the effect of depression on ART adherence were included.\n\nThe PEO approach was employed a systematic search strategy for this systematic review. The P (Population of interest) represented women living with HIV. The E (Exposure variable) represented WLWHIV and depression. The O (Outcome) variable represented antiretroviral non-adherence.",
      "reason": "The manuscript specifies population (women living with HIV), exposure and outcome (depression and ART adherence), eligible study designs (cross-sectional and cohort), global setting, and date range; it does not specify follow-up requirements or other study characteristic details (e.g., minimum follow-up duration), so the element is only partially met."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Peer reviewed cross-sectional and cohort study designed from across the world, published in English from 1 January 2000 to 30 December 2022 were included in the final analysis.",
      "reason": "The report characteristics are specified: peer-reviewed status, language restriction (English), and dissemination years (1 January 2000 to 30 December 2022)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction is provided between excluding studies because outcomes were not measured versus excluding because outcome results were not reported; the provided exclusion reasons do not make this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_19; text_11",
      "quote": "To show the correlation between depression and ART adherence, only cohort studies were included. However, crosssectional studies were narrated in systematic review.\n\nFor meta-analysis, only cohort study findings were included because it showed cause and effect relationship between depression and ART adherence in WLWHIV.",
      "reason": "The review specifies how studies were grouped for syntheses: cohort studies were pooled in the meta-analysis (to assess effect/causation) while cross-sectional studies were included only in the narrative synthesis, linking groups to the review objective."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_11; text_25",
      "quote": "For meta-analysis, only cohort study findings were included because it showed cause and effect relationship between depression and ART adherence in WLWHIV.\n\nLimitation. Articles published in other than the English language were not included, limitations that could have biased the overall outcomes.",
      "reason": "Rationales are provided for notable restrictions: cohort studies were restricted for meta-analysis to assess causation, and language restriction (English only) is noted with acknowledgement of its limitation."
    }
  ],
  "confidence": 85
}

